<template><article class="t-card t-match"><div class="t-meta"><span :class="['t-badge',match.status.toLowerCase()]">{{ match.status }} · Demo</span><small>Bo3 preview</small></div><div class="t-versus"><div><div class="t-crest" :style="{color:a.color,borderColor:a.color}">{{a.initials}}</div><strong>{{a.name}}</strong></div><div class="t-score">{{match.score}}<small>GAME {{match.game}}</small></div><div><div class="t-crest" :style="{color:b.color,borderColor:b.color}">{{b.initials}}</div><strong>{{b.name}}</strong></div></div><p class="t-sub">{{match.round}}</p><div class="t-card-bottom"><small>{{match.coverage}}</small><RouterLink class="t-button" :to="path('matches/'+match.id)">{{match.status==='Drafting'?'View draft & match':'View match'}}</RouterLink></div></article></template>
<script>
import { tournamentPath } from '../tournament.data.js';
export default {props:{match:{type:Object,required:true},tournament:{type:Object,required:true}},computed:{a(){return this.tournament.teams.find(t=>t.id===this.match.a)},b(){return this.tournament.teams.find(t=>t.id===this.match.b)}},methods:{path(segment){return tournamentPath(this.tournament.slug,segment)}}};
</script>
